  {tab==='fonts'&&isSuper&&<div style={{display:'grid',gap:18}}>
   <Guide><b>{t('settings.fonts_guide_title')}</b> {t('settings.fonts_guide')}</Guide>
   <div className="settings-card"><h2 className="settings-card-title"><Languages size={18}/> {t('settings.font_assignment')}</h2><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(200px,1fr))',gap:12}}>{([['global','settings.font_global'],['english','settings.font_english'],['hindi','settings.font_hindi'],['gujarati','settings.font_gujarati']] as const).map(([key,label])=><div className="form-group" key={key}><label className="form-label">{t(label)}</label><select className="form-select" value={fonts[key]} onChange={e=>setFonts({...fonts,[key]:e.target.value})}>{fontOptions.map(f=><option key={f.id} value={f.slug}>{f.name} · {f.source}</option>)}</select></div>)}</div><div className="font-preview" style={{fontFamily:`'${fontNameOf(fonts.global)}',sans-serif`}}><div className="lang-en">English: Centralized Karyalay Portal — Fast search and secure access.</div><div className="lang-hi">हिन्दी: कार्यालय पोर्टल में आपका स्वागत है।</div><div className="lang-gu">ગુજરાતી: કાર્યાલય પોર્ટલમાં આપનું સ્વાગત છે.</div></div><div className="settings-actions"><button className="btn btn-primary" onClick={saveFonts}>{t('settings.apply_fonts')}</button><button className="btn btn-secondary" onClick={()=>setFonts({global:'hind-vadodara',gujarati:'hind-vadodara',hindi:'noto-sans-devanagari',english:'inter'})}><RotateCcw size={14}/> {t('settings.restore_font_defaults')}</button></div></div>
   <div className="settings-card"><h2 className="settings-card-title"><Upload size={18}/> {t('settings.custom_font_upload')}</h2><Guide>{t('settings.custom_font_guide')}</Guide><div style={{display:'grid',gridTemplateColumns:'2fr 1fr 1fr',gap:10,marginTop:12}}><input className="form-input" placeholder={t('settings.font_family_name')} value={fontName} onChange={e=>setFontName(e.target.value)}/><select className="form-select" value={fontWeight} onChange={e=>setFontWeight(e.target.value)}>{[100,200,300,400,500,600,700,800,900].map(w=><option key={w}>{w}</option>)}</select><select className="form-select" value={fontStyle} onChange={e=>setFontStyle(e.target.value)}><option>normal</option><option>italic</option></select></div><div style={{display:'flex',gap:12,marginTop:10,flexWrap:'wrap'}}>{['latin','gujarati','devanagari'].map(s=><label key={s}><input type="checkbox" checked={fontScripts.includes(s)} onChange={e=>setFontScripts(e.target.checked?[...fontScripts,s]:fontScripts.filter(x=>x!==s))}/> {s}</label>)}</div><input type="file" accept=".woff2,.woff,.ttf,.otf" style={{marginTop:10}} onChange={e=>setFontFile(e.target.files?.[0]||null)}/><button className="btn btn-primary" style={{marginTop:10}} onClick={uploadFont}>{t('settings.upload_font')}</button></div>
   <div className="settings-card"><h2 className="settings-card-title"><Type size={18}/> {t('settings.installed_fonts')}</h2>{p.fontFamilies.map(f=><div key={f.id} className="setting-row"><div><div className="setting-title" style={{fontFamily:`'${f.css_family}',sans-serif`}}>{f.name} {!f.is_active&&<span style={{fontSize:10,color:'var(--color-warning)'}}>{t('settings.inactive_marker')}</span>}</div><div className="setting-help">{t('settings.font_meta',{source:f.source,scripts:(f.scripts||[]).join(', '),weights:f.files.length?f.files.map(x=>x.weight).join(', '):t('settings.package_managed')})}</div></div><div style={{display:'flex',gap:6,flexWrap:'wrap'}}><button className="btn btn-secondary" onClick={()=>setFonts({...fonts,global:f.slug})}>{t('settings.set_global')}</button><button className="btn btn-secondary" onClick={()=>router.patch(`/settings/fonts/${f.id}/status`,{is_active:!f.is_active},{preserveScroll:true,onError:e=>p.onError(String(Object.values(e)[0]||t('settings.font_status_failed')))})}>{f.is_active?t('settings.deactivate'):t('settings.activate')}</button>{!f.is_system&&<button className="queue-remove-btn" title={t('settings.delete_custom_font')} onClick={()=>confirm(t('settings.delete_font_confirm',{name:f.name}))&&router.delete(`/settings/fonts/${f.id}`,{preserveScroll:true,onSuccess:()=>p.onSuccess(t('settings.font_deleted')),onError:e=>p.onError(String(Object.values(e)[0]||t('settings.font_delete_failed')))})}><Trash2 size={16}/></button>}</div></div>)}</div>
  </div>}

