   <div className="settings-card"><h2 className="settings-card-title">{t('settings.exact_fields')}</h2><Guide>{t('settings.exact_fields_guide')}</Guide><div className="chip-list" style={{marginTop:10}}>{search.exact_fields.map(x=><span className="config-chip" key={x}>{x}<button onClick={()=>setSearch({...search,exact_fields:search.exact_fields.filter(v=>v!==x)})}><X size={12}/></button></span>)}</div><div style={{display:'flex',gap:8,marginTop:10}}><input className="form-input" value={exactField} placeholder={t('settings.field_name')} onChange={e=>setExactField(e.target.value)} onKeyDown={e=>e.key==='Enter'&&(e.preventDefault(),addExact())}/><button className="btn btn-secondary" onClick={addExact}><Plus size={14}/> {t('settings.add')}</button></div></div>
