     <div className="form-group"><label className="form-label">{t('settings.max_batch')}</label><input className="form-input" type="number" min={0} value={uploadSettings.max_batch_count} onChange={e=>setUploadSettings({...uploadSettings,max_batch_count:Number(e.target.value)})}/><div className="setting-help">{t('settings.max_batch_help')}</div></div>
