    <div className="setting-row"><div><div className="setting-title">{t('settings.possible_duplicate')}</div><div className="setting-help">{t('settings.possible_duplicate_help')}</div></div><Toggle checked={uploadSettings.possible_duplicate_warning} onChange={v=>setUploadSettings({...uploadSettings,possible_duplicate_warning:v})}/></div>
