   <div className="settings-card"><h2 className="settings-card-title"><LockKeyhole size={18}/> {t('settings.temporary_access')}</h2><Guide>{t('settings.temporary_access_guide')}</Guide><div className="settings-grid"><div className="form-group"><label className="form-label">{t('settings.default_expiry')}</label><input className="form-input" type="number" min={0} max={8760} value={accessMaturity.default_expiry_hours} onChange={e=>setAccessMaturity({...accessMaturity,default_expiry_hours:Number(e.target.value)})}/></div><div className="form-group"><label className="form-label">{t('settings.signed_download')}</label><input className="form-input" type="number" min={1} max={1440} value={accessMaturity.signed_download_minutes} onChange={e=>setAccessMaturity({...accessMaturity,signed_download_minutes:Number(e.target.value)})}/></div><div className="form-group"><label className="form-label">{t('settings.max_bulk_files')}</label><input className="form-input" type="number" min={1} max={500} value={accessMaturity.max_bulk_request_files} onChange={e=>setAccessMaturity({...accessMaturity,max_bulk_request_files:Number(e.target.value)})}/></div></div><button className="btn btn-primary" onClick={saveAccessMaturity}>{t('settings.save_temp_access')}</button></div>
